------------ define ------------
local QuestCookie = "DirectionalLastPassedQuestId"
local CountdownType = {--1：距离结束的时间   2：距离开启的时间
    closeRemain = 1,
    openRemain = 2
}
------------ define ------------


---@class DirectionalFightComponent
local DirectionalFightComponent = Class("DirectionalFightComponent", ECSComponent)
function DirectionalFightComponent:__init()
    self.name = "DirectionalFightComponent"
    self.timer = nil--计时器(距离关闭)
    self.timeCount = 0--用于显示的距离功能关闭的倒计时
    self.timerOpen = nil--计时器(距离开启)
    self.timeCountOpen = 0--用于显示的距离功能开启的倒计时
    self.maxWinCountOfType = 0--单个副本通关上限（获奖次数）
    self.maxDifficultyLevel = nil--最大副本难度等级(关卡表中的regionLevel)
    self.maxDailyWinCount = 0  --每日通关上限（获奖次数）

    ------------ 服务端数据 ------------
    self.questInfo = {}--key副本类型 value关卡最新Id
    self.remainTime = 0--home请求时服务端返回的距离功能关闭的时间 小于0已经结束
    self.openRemainTime = 0--home请求时服务端返回的距离开启时间 小于0已经开启

    ------------ 服务端数据 ------------
end

function DirectionalFightComponent:__delete()
    self.name = nil
    self.timer = nil
    self.timeCount = nil
    self.timerOpen = nil
    self.timeCountOpen = nil
    self.maxWinCountOfType = nil
    self.maxDifficultyLevel = nil

    ------------ 服务端数据 ------------
    self.questInfo = nil
    self.remainTime = nil
    self.openRemainTime = nil
    ------------ 服务端数据 ------------
    for i, v in pairs(CountdownType) do
        self:StopTimer(v)
    end
end

function DirectionalFightComponent:InitialDojo(jsonData)
    self.questInfo = jsonData.questInfo
    self.remainTime = jsonData.remainTime
    self.openRemainTime = jsonData.openRemainTime
    if self.remainTime > 0 then
        self:StartCountDown(self.remainTime, CountdownType.closeRemain)
    end
    if self.openRemainTime > 0 then
        self:StartCountDown(self.openRemainTime, CountdownType.openRemain)
    end
end

---定时副本参数表中的参数获取
function DirectionalFightComponent:SetArgVo()
    self.maxWinCountOfType = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting930, "DirectionalArgVo", 6).num)
    self.maxDailyWinCount = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting930, "DirectionalArgVo", 1).num)
    self.maxDifficultyLevel = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting930, "DirectionalArgVo", 4).num)
end

---@param type number
function DirectionalFightComponent:QuestAtNumPlusOne(type)
    type = checkNumber(type)
    for k, v in pairs(self.questInfo) do
        if checkNumber(v.type) == type then
            v.questAtNum = v.questAtNum + 1
        end
    end
end

---获取挑战次数用于显示的文本
---@return string 用于显示 如3/3
---@param type number 定时副本类型表的id
function DirectionalFightComponent:GetWinCountText(type)
    type = checkNumber(type)
    local leftNum
    local wonCount = 0
    for k, v in pairs(self.questInfo) do
        if checkNumber(v.type) == type then
            leftNum = self.maxWinCountOfType - checkNumber(v.questAtNum)
        end
        wonCount = wonCount + checkNumber(v.questAtNum)
    end
    leftNum = math.min(leftNum, self.maxDailyWinCount - wonCount)
    leftNum = math.max(leftNum, 0)
    return string.format("%d/%d", leftNum, self.maxWinCountOfType)
end

---获取养成升级后定向作战内的弹窗数据本地缓存，没有的话初始化一个
---@return table --key:定时副本类型表id --value:--times2为解锁弹窗，1为难度选择红点，0为消除--difficulty解锁难度
function DirectionalFightComponent:GetPlayerPrefs()
    local key = "DirectionalFightUnlockCondition"
    local data = {}
    local cache = CfUtils.GetLocalData(key, "")
    if not string.isEmpty(cache) then
        data = table.deserialize(cache)
    else
        local directionalTypeVo = CfUtils.GetWholeVo(AutoIds.IdSetting933, "DirectionalTypeVo")
        for k, v in pairs(directionalTypeVo) do
            data[checkString(v.id)] = {
                times = 0,
                difficulty = 1,
            }
        end
        self:SetPlayerPrefs(data)
    end
    return data
end

---@param data table --key:定时副本类型表id --value:2为解锁弹窗，1为难度选择红点，0为消除
function DirectionalFightComponent:SetPlayerPrefs(data)
    local key = "DirectionalFightUnlockCondition"
    CfUtils.WriteLocalData(key, table.serialize(data))
end

---维护养成升级后定向作战内的弹窗数据本地缓存 2为解锁弹窗，1为难度选择红点，0为消除
---@param type string 定时副本类型表id
function DirectionalFightComponent:MaintainUnlockedCache(type)
    type = checkString(type)
    local data = self:GetPlayerPrefs()
    data[type].times = data[type].times - 1
    self:SetPlayerPrefs(data)
end

function DirectionalFightComponent:StopTimer(type)
    if type == CountdownType.closeRemain then
        if not isNull(self.timer) then
            CDTimerModule:RemoveCD(self.timer)
            self.timer = nil
        end
    elseif type == CountdownType.openRemain then
        if not isNull(self.timerOpen) then
            CDTimerModule:RemoveCD(self.timerOpen)
            self.timerOpen = nil
        end
    end
end

---开始倒计时
---@param leftTime number 倒计时
---@param type number 类型  1：距离结束的时间   2：距离开启的时间
function DirectionalFightComponent:StartCountDown(leftTime, type)
    self:StopTimer(type)
    if type == CountdownType.closeRemain then
        self.timer = CDTimerModule:AddCD(1, function (count, id)
            self.timeCount = count
        end, leftTime, true, true, true)
    elseif type == CountdownType.openRemain then
        self.timerOpen = CDTimerModule:AddCD(1, function (count, id)
            self.timeCountOpen = count
        end, leftTime, true, true, true)
    end
end

