function DirectionalFightComponent:IsShowNextBtn(questVo, passType)
    if passType == 1 then
        self:QuestAtNumPlusOne(questVo.type)
    end
    local hasWinCount = self:HasWinCount(questVo.type)
    -- local isMaxDifficulty = self:IsMaxDifficulty(questVo.regionLevel)
    local nextQuestVo = self:GetNextDifficultyQuestData(questVo.id)
    if isNull(nextQuestVo) then
        return false
    end
    local isTeamRatingCondition = self:IsTeamRatingConditionMeet(nextQuestVo.regionLevel)
    -- local isShowNextQuest = hasWinCount and (not isMaxDifficulty) and isTeamRatingCondition
    local isShowNextQuest = hasWinCount and isTeamRatingCondition
    return isShowNextQuest and (passType == 1)
end

---尝试打开难度解锁的dialog
---@param questId number 定时副本关卡表中的关卡id, 战斗结算界面传当前通关的关卡id
function DirectionalFightComponent:TryOpenDifficultyUnlockDialog(questId)
    local questVo = QuestConfMgr:GetInstance():GetQuestVoById(questId)
    local difficulty = checkNumber(questVo.regionLevel)
    local UIModule = CS.Engine.UI.UIModule
    if self:IsUpdateQuestLevel() then
        UIModule.OpenDialog({ id = Constants.UITypeIds.DirectionalUpgradePopup, parameters = {curPassedDifficulty = difficulty - 1,  newDifficulty = difficulty}})
    end

end

---设置最新通关的定向作战关卡
---@param questId number
function DirectionalFightComponent:SetLastPassedQuestId(questId)
    questId = checkNumber(questId)
    local lastQuestId = checkNumber(self:GetLastPassedQuestId())
    KCookie.Set("DirectionalUpgradeQuestLevel", questId ~= lastQuestId)
    KCookie.Set(QuestCookie, questId)
end

---升级关卡
function DirectionalFightComponent:IsUpdateQuestLevel()
    local ret = KCookie.Get("DirectionalUpgradeQuestLevel")
    KCookie.Set("DirectionalUpgradeQuestLevel", nil)
    return checkBool(ret)
end

function DirectionalFightComponent:GetLastPassedQuestId()
    return KCookie.Get(QuestCookie)
end

function DirectionalFightComponent:IsQuestOpened(questId)
    local lastPassedQuestVo = QuestConfMgr:GetInstance():GetQuestVoById(questId)
    for k, v in pairs(self.questInfo) do
        if checkNumber(lastPassedQuestVo.type) == checkNumber(v.type) then
            if checkNumber(v.isOpen) == 1 then
                return true
            end
        end
    end
    return false
end

---获取下一难度的关卡数据
function DirectionalFightComponent:GetNextDifficultyQuestData(curPassedQuestId)
    local curPassedQuestVo = QuestConfMgr:GetInstance():GetQuestVoById(curPassedQuestId)
    if self:IsMaxDifficulty(curPassedQuestVo.regionLevel) then--当前为最大难度，继续返回当前关卡数据
        return QuestConfMgr:GetInstance():GetQuestVoById(curPassedQuestId)
    end
    local ids = string.split(CfUtils.GetIdGroupData(AutoIds.IdSetting931, checkString(curPassedQuestVo.type), "ids")[1], ";")
    local curPassedIndex = table.indexof(ids, checkString(curPassedQuestId))
    local nextQuestId = ids[curPassedIndex + 1]
    return QuestConfMgr:GetInstance():GetQuestVoById(nextQuestId)
end

---当前难度是否为最大难度
---@param curDifficulty number 当前的副本难度
function DirectionalFightComponent:IsMaxDifficulty(curDifficulty)
    curDifficulty = checkNumber(curDifficulty)
    return curDifficulty >= self.maxDifficultyLevel
end

