---当前类型副本是否拥有获奖次数
---@param type number 定时副本类型表id
function DirectionalFightComponent:HasWinCount(type)
    type = checkNumber(type)
    local remainingWinCount = self:GetRemainingWinCount(type)
    return remainingWinCount > 0
end

---获取当前类型副本剩余获奖次数
---@param type number 定时副本类型表id
function DirectionalFightComponent:GetRemainingWinCount(type)
    type = checkNumber(type)
    for k, v in pairs(self.questInfo) do
        if checkNumber(v.type) == type then
            return self.maxWinCountOfType - checkNumber(v.questAtNum)
        end
    end
end

---获取服务端questInfo中当前type的数据
---@param type number 定时副本类型表id
function DirectionalFightComponent:GetQuestInfoByType(type)
    type = checkNumber(type)
    for k, v in pairs(self.questInfo) do
        if checkNumber(v.type) == type then
            return v
        end
    end
end

---获取难度等级的图片路径
---@param isUnlocked boolean 是否解锁，高亮状态传true,灰暗状态传false
---@param level number 难度等级
function DirectionalFightComponent:GetLevelIconPath(isUnlocked, level)
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting121, "CardUpgradeStarLimitVo", level)
    local path = string.format("Arts/Icons/Directional/directional_level_difficulty_%s_%s.png", isUnlocked and "on" or "on", string.lower(vo.name))
    return path
end

function DirectionalFightComponent:GetLevelIconPath2(level)
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting121, "CardUpgradeStarLimitVo", level)
    local path = string.format("Arts/Icons/Directional/directional_settlement_level_%s.png", string.lower(vo.name))
    return path
end

return DirectionalFightComponent